# ResetParts: put every movable part back to its start pose (kit pallet / pipe buffer), studs down, clear the bead
# traces - lets DemoCycle2 run again. Generated by build_station2.py
from robodk.robolink import *
from robodk.robomath import *
RDK = Robolink()
frame = RDK.Item('Logistics', ITEM_TYPE_FRAME)
START = {'Part flange': [[0.0, 1.0, 0.0, -7400.0], [-1.0, 0.0, 0.0, 2850.0], [0.0, -0.0, 1.0, 230.0], [0.0, 0.0, 0.0, 1.0]], 'Part elbow': [[0.0, 1.0, 0.0, -7400.0], [-1.0, 0.0, 0.0, 2200.0], [0.0, -0.0, 1.0, 200.0], [0.0, 0.0, 0.0, 1.0]], 'Part pipe': [[0.0, 1.0, 0.0, -5250.0], [-1.0, 0.0, 0.0, 3231.0], [0.0, -0.0, 1.0, 419.0], [0.0, 0.0, 0.0, 1.0]], 'Part flange 2': [[0.0, 1.0, 0.0, -6800.0], [-1.0, 0.0, 0.0, 2850.0], [0.0, -0.0, 1.0, 230.0], [0.0, 0.0, 0.0, 1.0]]}
for name, rows in START.items():
    part = RDK.Item(name, ITEM_TYPE_OBJECT)
    if part.Valid():
        part.setParent(frame)
        part.setPose(Mat(rows))
studs = RDK.Item('Clamp studs', ITEM_TYPE_OBJECT)
if studs.Valid():
    studs.setVisible(False)
RDK.Spray_Clear()
RDK.setParam("GRIPPER", "OPEN")
RDK.setParam("POS_STUDS", "DOWN")
